flow.script:

package main

import (
    "fmt"
    "os"
    "host/vars"
)

func main() {
    // Print all pipeline variables then exit
    fmt.Println("========== Pipeline Variables ==========")
    allVars := vars.GetAll()
    for name, val := range allVars {
        fmt.Printf("  %-20s = %v\n", name, val)
    }
    fmt.Println("========================================")
    os.Exit(0)
}
